-- PT104-S1-Q7. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT104-S1-Q7$batch03$ AND q.stimulus=$batch03$Because of the recent recession in Country A, most magazines published there have experienced decreases in advertising revenue, so much so that the survival of the most widely read magazines is in grave doubt. At the same time, however, more people in Country A are reading more magazines than ever before, and the number of financially successful magazines in Country A is greater than ever.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy in the information above?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT104-S1-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT104-S1-Q7$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S1-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT104-S1-Q7$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Most magazines have lost advertising revenue in the recession, enough to put the most widely read magazines in danger.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$People are reading more magazines than ever, and more magazines are financially successful than ever?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Notice the two groups the stimulus names. The danger is to the *most widely read* magazines. The success is counted across magazines in general. If smaller magazines do not depend much on advertising, an ad slump would hurt the big ones while the rest thrive on more readers. Look for something that separates how the two kinds of magazine make money.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a difference in revenue source between the most widely read magazines and the others.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT104-S1-Q7$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Cheaper ad rates would explain the fall in ad revenue. They do nothing to explain why more magazines than ever are succeeding.$batch03$), ($batch03$B$batch03$, $batch03$Television audiences do not tell us anything about magazine revenue or magazine success.$batch03$), ($batch03$C$batch03$, $batch03$Only the biggest magazines live on advertising, so the ad slump threatens them. Everyone else lives on circulation, and more people are reading, so more of them succeed. Both halves of the stimulus now fit.$batch03$), ($batch03$D$batch03$, $batch03$If readers cut subscriptions and borrow copies, circulation revenue falls too. That makes the record number of successful magazines even harder to explain.$batch03$), ($batch03$E$batch03$, $batch03$New magazines surviving is one more sign of success. It repeats the surprising fact instead of explaining it.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT104-S1-Q7$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
